INSERT OR IGNORE INTO analysis_snapshots (id, profile_id, snapshot_reason, primary_cluster, secondary_cluster, relevance_score, authority_score, engagement_rate, monetization_signals, audience_alignment, tier, tier_reason, content_style, content_summary, is_approved, rejection_reason, snapshotted_at) VALUES (1, 129, 'reverify', 'masculinity', 'mindset', 98, 5.8, 0.716037273173124, '["event sales","paid community","coaching"]', 0, 'C', '', 'Unknown', 'This influencer, @manaligned, promotes ''men''s work'' focused on developing a strong masculine identity, personal responsibility, and a sense of brotherhood. Their content strategy revolves around motivating men to take ''massive action,'' cultivate discipline, and join their immersive ''Winter Camp'' events and mastermind calls for deep personal growth and community.', NULL, NULL, '2026-03-05 00:09:08');
